import { tags } from "typia";

/**
 * Standard pagination configuration for API responses.
 *
 * Provides consistent pagination parameters across all list-based API
 * operations, supporting flexible page sizing and navigation through large
 * result sets. This standard approach ensures predictable performance and user
 * experience across the platform.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IPagination = {
  /** Page number for result set navigation (1-based indexing). */
  page: number & tags.Type<"int32"> & tags.Minimum<1>;

  /** Number of items per page with maximum limit of 100 for performance. */
  limit: number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>;

  /**
   * Field name to sort results by. Defaults to primary sort field if not
   * specified.
   */
  sort_by?: string | undefined;

  /** Sort direction: ascending or descending order. */
  sort_order?: "asc" | "desc" | undefined;
};
